<template><n-drawer :show="show" placement="right" :width="drawerWidth" :aria-label="tool?.displayName || t('detail.name')" @update:show="$emit('update:show', $event)"><n-drawer-content :title="tool?.displayName || ''"><div v-if="tool" class="tool-detail-drawer" data-responsive-width="min(520px, calc(100vw - 24px))"><n-space vertical>
  <n-descriptions :column="1" bordered size="small"><n-descriptions-item :label="t('detail.name')">{{tool.name}}</n-descriptions-item><n-descriptions-item :label="t('detail.category')">{{tool.category}}</n-descriptions-item><n-descriptions-item :label="t('detail.description')">{{tool.description}}</n-descriptions-item></n-descriptions>
  <n-button data-action="favorite" size="small" @click="$emit('toggle-favorite',tool.name)">{{tool.isFavorite?t('favorites.remove'):t('favorites.add')}}</n-button>
  <section v-if="tool.localVersion||tool.localPath" class="detail-section"><h3>{{t('detail.local_env')}}</h3><n-tag v-if="tool.localVersion" type="warning">{{tool.localVersion}}</n-tag><CopyableValue v-if="tool.localPath" :value="tool.localPath"/><n-space><n-button v-if="tool.localPath&&!tool.installed" data-action="migrate" size="tiny" @click="$emit('migrate',tool.name,tool.localPath)">{{t('detail.migrate_to_xdev')}}</n-button><n-button v-if="tool.localPath&&tool.installed" data-action="switch-local" size="tiny" @click="$emit('switch-local',tool.name)">{{t('detail.switch_to_local')}}</n-button></n-space></section>
  <section class="detail-section"><h3>{{t('detail.installed_versions')}}</h3><VersionList :versions="installedVersions" mode="installed" :t="t" @use="v=>$emit('use-version',tool.name,v)" @uninstall="v=>$emit('uninstall-version',tool.name,v)"/></section>
  <section class="detail-section"><h3>{{t('detail.available_versions')}}</h3><VersionList :versions="availableVersions" mode="available" :limit="showCount" :t="t" @install="v=>$emit('install',tool.name,v)" @show-all="$emit('show-more')"/></section>
  <section class="detail-section"><h3>{{t('detail.install_custom')}}</h3><n-space><n-input v-model:value="customVersion"/><n-button :disabled="!customVersion" @click="$emit('install',tool.name,customVersion)">{{t('btn.install')}}</n-button></n-space></section>
</n-space></div></n-drawer-content></n-drawer></template>
<script setup>import{nextTick,ref,watch}from'vue';import{NButton,NDescriptions,NDescriptionsItem,NDrawer,NDrawerContent,NInput,NSpace,NTag}from'naive-ui';import CopyableValue from './CopyableValue.vue';import VersionList from './VersionList.vue';const drawerWidth='min(520px, calc(100vw - 24px))';const props=defineProps({show:Boolean,tool:Object,installedVersions:{type:Array,default:()=>[]},availableVersions:{type:Array,default:()=>[]},showCount:{type:Number,default:10},returnFocusTo:Object,t:{type:Function,required:true}});defineEmits(['update:show','toggle-favorite','migrate','switch-local','use-version','uninstall-version','install','show-more']);const customVersion=ref('');watch(()=>props.tool?.name,()=>{customVersion.value=''});watch(()=>props.show,async(show,was)=>{if(!show)customVersion.value='';if(!show&&was){await nextTick();props.returnFocusTo?.focus?.();}});</script>
<style scoped>.detail-section{padding:var(--xdev-space-3);border:1px solid var(--xdev-border-subtle);border-radius:var(--xdev-radius-md)}h3{margin:0 0 var(--xdev-space-3);font-size:var(--xdev-font-size-md)}</style>
